import { awardSlots, awardWallSlots } from "./imageSlots";
import type { ImageSlot } from "./imageSlots";

/**
 * The fourteen awards standing on the shelves of the About photograph.
 *
 * Two things are authored here, and neither can be derived from the files.
 *
 * The first is where each trophy stands, as a percentage of `aboutBand.webp`.
 * Because the band keeps the plate's 1920x800 ratio, a percentage lands on the
 * same trophy at every width and every zoom.
 *
 * These numbers are generated by `tools/build-award-wall.mjs`, which matches
 * each cut-out against the band rather than guessing at its edges. That matters
 * because the wall lays a trophy's own cut-out over the trophy baked into the
 * photograph: a few pixels out and it ghosts against itself. Scanning for the
 * gold and black of a frame edge was tried first and produced boxes 15% to
 * 118% away from the cut-outs' own aspect ratios, because the scan picks up
 * neighbouring frames and the shadow under the shelf. The match scores in the
 * comments are the mean channel difference over each cut-out's opaque pixels,
 * on a 0-255 scale; they bottom out near 10 rather than at 0 because the band
 * and the cut-outs were WebP-encoded separately. Re-run the tool after any
 * re-encode of either.
 *
 * The second is the copy. Names and years come off the delivered filenames,
 * but the issuing body of an award is a claim, so only SME100 is named: it is
 * the one programme in the set whose criteria are on public record. The other
 * thirteen summaries say what the recognition is for and stop there, because
 * inventing an organiser would invent a credential.
 */
export type Award = {
  /** Dialog size. */
  slot: ImageSlot;
  /** Wall size, laid over the trophy standing in the band. */
  wallSlot: ImageSlot;
  name: string;
  year: string;
  summary: string;
  /* Percentages of the band. `top` and `height` come from the shelf. */
  left: number;
  width: number;
  top: number;
  height: number;
};

/* Generated by tools/build-award-wall.mjs. Do not hand-edit: re-run it. */
