export const AWARDS: Award[] = RECORDS.map((record, index) => {
  const slot = awardSlots[record.id];
  const wallSlot = awardWallSlots[record.id];
  if (!slot || !wallSlot) throw new Error(`awardWall: no cut-out shipped for ${record.id}`);
  const place = PLACES[index];
  if (!place) throw new Error(`awardWall: no shelf position for ${record.id}`);

  return {
    ...record,
    ...place,
    /* Alt text belongs to the picture, and the picture is the trophy. The wall
       copy is decorative: it sits on top of the same trophy in the photograph
       and its button already carries the name. */
    slot: { ...slot, alt: `The ${record.name} ${record.year} trophy` },
    wallSlot,
  };
});
